        <div 
          className="absolute inset-0 bg-cover bg-center bg-no-repeat transform scale-105"
          style={{ backgroundImage: `url('${event.heroImage}')` }}
        />
        {/* Gradient Overlay */}
        <div className={`absolute inset-0 bg-gradient-to-t ${isBday ? 'from-black via-black/40' : 'from-black/80 via-black/20'} to-transparent`} />

        {/* Content */}
        <div className="absolute bottom-0 left-0 w-full p-8 pb-12 flex flex-col items-center text-center text-white">
          <motion.div
            initial={{ y: 30, opacity: 0 }}
            animate={{ y: 0, opacity: 1 }}
            transition={{ duration: 0.8 }}
          >
            <p className="text-xs md:text-sm font-medium tracking-[0.2em] mb-4 text-primary/90 uppercase opacity-90">
              {isWedding ? 'Junte-se a nós no casamento de' : isBday ? 'Você foi convidado para' : 'Bem-vindo ao'}
            </p>
            <h1 className={`${theme.fontHead} text-5xl md:text-6xl leading-tight mb-2`}>
              {event.title}
            </h1>
            <div className="h-px w-12 bg-primary/60 my-4 mx-auto" />
            <p className={`${theme.fontHead} text-lg md:text-xl italic font-light tracking-wide text-white/90`}>
              {event.date}
            </p>
          </motion.div>

          <div className="mt-6 animate-bounce">
            <span className="material-symbols-outlined text-white/50 text-3xl">keyboard_arrow_down</span>
          </div>
        </div>
      </div>

      {/* Main Content Container */}
      <main className="px-5 -mt-6 relative z-10 flex flex-col gap-6">

