const InvitationView: React.FC = () => {
  const { id } = useParams();
  const event = getEventById(id || '');
  const [isRSVPOpen, setRSVPOpen] = useState(false);

  if (!event) return null;

  // Theme Config Logic
  const isWedding = event.type === ThemeType.WEDDING;
  const isBday = event.type === ThemeType.BIRTHDAY;

  // Custom Color Handling
  // We use CSS variables to handle the dynamic coloring efficiently without inline clutter
  const customStyle = {
    '--theme-accent': event.themeColor || '#C5A028',
  } as React.CSSProperties;

  // Dynamic classes based on theme
  const theme = {
    fontHead: isWedding ? 'font-serif' : isBday ? 'font-display font-black tracking-tight' : 'font-display font-bold',
    fontBody: isWedding ? 'font-serif' : 'font-display',
    bg: isBday ? 'bg-background-dark' : 'bg-background-light dark:bg-background-dark',
    text: isBday ? 'text-white' : 'text-gray-900 dark:text-white',
    card: isBday ? 'bg-white/5 border-white/10' : 'bg-surface-light dark:bg-surface-dark border-black/5 dark:border-white/5',
    timelineLine: isBday ? 'bg-gray-700' : 'bg-gray-200 dark:bg-gray-700',
    navBar: isBday ? 'bg-[#0F0F16]/85 border-white/5' : 'bg-[#FAF9F6]/85 dark:bg-[#171611]/85 border-white/20 dark:border-white/5'
  };

  // Animation Variants
  const staggerContainer = {
    hidden: { opacity: 0 },
    visible: {
      opacity: 1,
      transition: {
        staggerChildren: 0.15,
        delayChildren: 0.1
      }
    }
  };

  const fadeInUp = {
    hidden: { y: 30, opacity: 0 },
    visible: { 
      y: 0, 
      opacity: 1,
      transition: { duration: 0.6, ease: "easeOut" }
    }
  };

  const timelineItemVariant = {
    hidden: { x: -20, opacity: 0 },
    visible: { 
      x: 0, 
      opacity: 1,
      transition: { duration: 0.5, ease: "easeOut" }
    }
  };

  const scaleIn = {
    hidden: { scale: 0.95, opacity: 0 },
    visible: { 
      scale: 1, 
      opacity: 1,
      transition: { duration: 0.6, ease: "easeOut" }
    }
  };

  return (
    <div style={customStyle} className={`min-h-screen relative pb-28 ${theme.bg} ${theme.text} ${theme.fontBody}`}>

      {/* Widget */}
      <TocaPlayer trackName={event.musicTrack} isDark={isBday || true} />

      {/* Hero Section */}
      <div className="relative h-[85vh] w-full overflow-hidden rounded-b-3xl shadow-2xl">
        {/* Background Image */}
        <div 
          className="absolute inset-0 bg-cover bg-center bg-no-repeat transform scale-105"
          style={{ backgroundImage: `url('${event.heroImage}')` }}
        />
        {/* Gradient Overlay */}
        <div className={`absolute inset-0 bg-gradient-to-t ${isBday ? 'from-black via-black/40' : 'from-black/80 via-black/20'} to-transparent`} />

        {/* Content */}
        <div className="absolute bottom-0 left-0 w-full p-8 pb-12 flex flex-col items-center text-center text-white">
          <motion.div
            initial={{ y: 30, opacity: 0 }}
            animate={{ y: 0, opacity: 1 }}
            transition={{ duration: 0.8 }}
          >
            <p className="text-xs md:text-sm font-medium tracking-[0.2em] mb-4 uppercase opacity-90" style={{ color: event.themeColor || '#C5A028' }}>
              {isWedding ? 'Junte-se a nós no casamento de' : isBday ? 'Você foi convidado para' : 'Bem-vindo ao'}
            </p>
            <h1 className={`${theme.fontHead} text-5xl md:text-6xl leading-tight mb-2 drop-shadow-lg`}>
              {event.title}
            </h1>
            <div className="h-px w-12 bg-white/60 my-4 mx-auto" />
            <p className={`${theme.fontHead} text-lg md:text-xl italic font-light tracking-wide text-white/90`}>
              {event.date}
            </p>
          </motion.div>

          <div className="mt-6 animate-bounce">
            <span className="material-symbols-outlined text-white/50 text-3xl">keyboard_arrow_down</span>
          </div>
        </div>
      </div>

      {/* Main Content Container */}
      <main className="px-5 -mt-6 relative z-10 flex flex-col gap-6">

        {/* Our Story / Description Section */}
        <motion.div 
          initial={{ y: 20, opacity: 0 }}
          whileInView={{ y: 0, opacity: 1 }}
          viewport={{ once: true }}
          className={`${theme.card} p-8 rounded-2xl shadow-sm border`}
        >
          <div className="flex flex-col items-center text-center">
            <span className={`material-symbols-outlined text-3xl mb-3`} style={{ color: 'var(--theme-accent)' }}>
              {isWedding ? 'favorite' : 'celebration'}
            </span>
            <h2 className={`${theme.fontHead} text-3xl font-medium mb-4`}>
              {isWedding ? 'Nossa História' : 'O Evento'}
            </h2>
            <p className={`leading-relaxed font-light text-sm md:text-base opacity-80`}>
              {event.description}
            </p>
          </div>
        </motion.div>

        {/* Timeline Section */}
        <motion.div 
           initial="hidden"
           whileInView="visible"
           viewport={{ once: true, margin: "-50px" }}
           variants={staggerContainer}
           className={`${theme.card} p-6 rounded-2xl shadow-sm border`}
        >
          <motion.h2 variants={fadeInUp} className={`${theme.fontHead} text-2xl font-medium mb-6 px-2`}>Programação</motion.h2>
          <div className="relative space-y-6 pl-2">
            {/* Vertical Line */}
            <motion.div variants={fadeInUp} className={`absolute left-[27px] top-2 bottom-2 w-px ${theme.timelineLine}`} />

            {event.timeline.map((item, index) => (
              <motion.div 
                key={index} 
                variants={timelineItemVariant}
                className="flex items-start gap-4 relative z-10"
              >
                <div className="flex-none w-14 pt-1">
                  <span className={`text-sm font-bold`} style={{ color: 'var(--theme-accent)' }}>{item.time.split(' ')[0]}</span>
                </div>
                <div 
                  className={`flex-none w-3 h-3 rounded-full mt-2 ring-4 ring-offset-0 ${isBday ? 'ring-[#1A1A24]' : 'ring-[#FFFFFF] dark:ring-[#211e11]'}`}
                  style={{ backgroundColor: index === 0 ? 'var(--theme-accent)' : '#9ca3af' }} 
                />
                <div className="flex-1 pb-2">
                  <h3 className={`${theme.fontHead} text-lg leading-none mb-1`}>{item.title}</h3>
                  <p className="text-xs opacity-60">{item.description}</p>
                </div>
              </motion.div>
            ))}
          </div>
        </motion.div>

        {/* Venue Section */}
        <motion.div 
          initial="hidden"
          whileInView="visible"
          viewport={{ once: true, margin: "-50px" }}
          variants={staggerContainer}
          className={`${theme.card} overflow-hidden rounded-2xl shadow-sm border mb-8`}
        >
          <motion.div variants={scaleIn} className="relative h-48 w-full bg-gray-200">
            <div 
              className="absolute inset-0 bg-cover bg-center"
              style={{ backgroundImage: `url('${event.mapImage || event.heroImage}')` }}
            />
            <div className="absolute inset-0 bg-black/10 flex items-center justify-center">
              <span className="material-symbols-outlined text-white text-5xl drop-shadow-lg" style={{ color: 'var(--theme-accent)' }}>location_on</span>
            </div>
            <button className="absolute bottom-3 right-3 bg-white dark:bg-black text-black dark:text-white text-xs font-bold px-3 py-1.5 rounded shadow-md hover:opacity-90 transition-opacity">
              Ver no Mapa
            </button>
          </motion.div>
          <motion.div variants={fadeInUp} className="p-6">
            <h2 className={`${theme.fontHead} text-2xl font-medium mb-2`}>Localização</h2>
            <p className="text-sm opacity-80 leading-relaxed">
              {event.locationName}<br/>
              {event.address}
            </p>
          </motion.div>
        </motion.div>

        <div className="h-8"></div>
      </main>

      {/* Glassmorphic Bottom Navigation */}
      <div className="fixed bottom-0 left-0 w-full z-50">
        {/* Gradient fade */}
        <div className={`absolute bottom-full left-0 w-full h-8 bg-gradient-to-t ${isBday ? 'from-background-dark/80' : 'from-background-light/80 dark:from-background-dark/80'} to-transparent pointer-events-none`} />

        <div className={`${theme.navBar} backdrop-blur-xl border-t pb-8 pt-3 px-6 shadow-[0_-4px_20px_rgba(0,0,0,0.05)]`}>
          <div className="flex items-center justify-between gap-2 max-w-md mx-auto">
            <NavButton icon="map" label="Mapa" accentColor={event.themeColor} />
            <NavButton icon="redeem" label="Presentes" accentColor={event.themeColor} />
            <NavButton icon="chat_bubble" label="Mural" accentColor={event.themeColor} />

            <button 
              onClick={() => setRSVPOpen(true)}
              style={{ backgroundColor: event.themeColor || '#C5A028', color: event.themeColor === '#1B365D' ? '#FFF' : '#171611' }}
              className="flex-1 ml-2 h-12 hover:opacity-90 active:scale-95 rounded-xl flex items-center justify-center gap-2 font-bold text-sm tracking-wide shadow-lg transition-all"
            >
              <span>Confirmar</span>
              <span className="material-symbols-outlined text-lg">arrow_forward</span>
            </button>
          </div>
        </div>
      </div>

      {/* RSVP Modal reused */}
      <BottomSheet 
        isOpen={isRSVPOpen} 
        onClose={() => setRSVPOpen(false)} 
        title="Confirmar Presença"
        themeClasses={isBday ? 'bg-[#1A1A24] text-white' : 'bg-surface-light dark:bg-surface-dark text-gray-900 dark:text-white'}
      >
        <form className="space-y-4" onSubmit={(e) => { e.preventDefault(); setRSVPOpen(false); }}>
          <div className="space-y-1">
            <label className="text-sm font-semibold opacity-70">Nome Completo</label>
            <input type="text" placeholder="João Silva" className={`w-full p-4 rounded-xl bg-transparent border-2 focus:outline-none ${isBday ? 'border-white/20 focus:border-white' : 'border-black/10 focus:border-black dark:border-white/10'}`} required />
