// ============================================================================
// HELPER: COUNTDOWN TIMER
// ============================================================================
const CountdownTimer: React.FC<{ targetDate: string }> = ({ targetDate }) => {
  const [timeLeft, setTimeLeft] = useState({ days: 0, hours: 0, minutes: 0, seconds: 0 });

  useEffect(() => {
    const calculateTimeLeft = () => {
      const difference = +new Date(targetDate) - +new Date();
      if (difference > 0) {
        setTimeLeft({
          days: Math.floor(difference / (1000 * 60 * 60 * 24)),
          hours: Math.floor((difference / (1000 * 60 * 60)) % 24),
          minutes: Math.floor((difference / 1000 / 60) % 60),
          seconds: Math.floor((difference / 1000) % 60),
        });
      }
    };
    const timer = setInterval(calculateTimeLeft, 1000);
    calculateTimeLeft();
    return () => clearInterval(timer);
  }, [targetDate]);

  const TimeBox = ({ val, label }: { val: number, label: string }) => (
    <div className="flex flex-col items-center">
      <div className="w-14 h-14 md:w-16 md:h-16 border border-[#BF9B30]/30 bg-[#0F1419]/50 backdrop-blur-sm rounded-lg flex items-center justify-center mb-1 shadow-lg shadow-black/20">
        <span className="text-[#BF9B30] text-xl md:text-2xl font-serif font-bold tabular-nums">
          {val < 10 ? `0${val}` : val}
        </span>
      </div>
      <span className="text-[9px] uppercase tracking-widest text-gray-500">{label}</span>
    </div>
  );

  return (
    <div className="flex gap-3 md:gap-6 justify-center py-6">
      <TimeBox val={timeLeft.days} label="Dias" />
      <TimeBox val={timeLeft.hours} label="Hrs" />
      <TimeBox val={timeLeft.minutes} label="Min" />
      <TimeBox val={timeLeft.seconds} label="Seg" />
    </div>
  );
};

